/**
 * Dynasty registry & realm selectors — the single source of "who ruled what, when".
 * Data is generated by scripts/registry/build-registry.ts from docs/historical_data/*.json.
 * Same year → same answer (deterministic; no randomness, no AI).
 */
import dynastiesJson from './generated/dynasties.json';
import realmsJson from './generated/realms.json';

export type Family = 'persian' | 'arab' | 'turkic' | 'greek' | 'nomadic' | 'foreign' | 'semitic';
export type Relation = 'direct' | 'suzerain' | 'vassal' | 'governor' | 'influence' | 'occupation' | 'branch';
export type Confidence = 'low' | 'medium' | 'high';

export interface RegistryDynasty {
  id: string;
  name: { en: string; fa: string };
  family: Family;
  color: string;
  emblemSeed: number;
  overlordId?: string;
  start: number;
  end: number;
}

export interface Realm {
  dynastyId: string;
  regionId: string;
  start: number;
  end: number;
  relation: Relation;
  confidence: Confidence;
  sourceFile: string;
  /** false for satrapies/provinces outside the 12 board regions (Lydia, Bactria, Armenia …) */
  core: boolean;
}

const CONF: Confidence[] = ['low', 'medium', 'high'];

export const dynasties: RegistryDynasty[] = dynastiesJson as RegistryDynasty[];
const byId = new Map(dynasties.map(d => [d.id, d]));
export const getDynasty = (id: string) => byId.get(id);

const coreRegions = new Set<string>(realmsJson.coreRegions);

/** All realms, sorted by start year. */
export const realms: Realm[] = (realmsJson.rows as unknown as [number, string, number, number, Relation, number, number][]).map(
  ([d, regionId, start, end, relation, conf, file]) => ({
    dynastyId: dynasties[d].id,
    regionId,
    start,
    end,
    relation,
    confidence: CONF[conf],
    sourceFile: realmsJson.files[file],
    core: coreRegions.has(regionId),
  })
);

/** Realms in force at `year` (inclusive bounds), optionally for one region. */
export function getRealmsAt(year: number, regionId?: string): Realm[] {
  return realms.filter(r => year >= r.start && year <= r.end && (!regionId || r.regionId === regionId));
}

/** Distinct dynasties ruling (in any capacity) at `year`. */
export function getActiveDynastyIds(year: number, opts: { coreOnly?: boolean } = {}): string[] {
  const ids = new Set<string>();
  for (const r of getRealmsAt(year)) if (!opts.coreOnly || r.core) ids.add(r.dynastyId);
  return [...ids].sort();
}

/** "In 1000 AD, N dynasties ruled here" — the headline counter. */
export function countDynastiesAt(year: number, opts: { coreOnly?: boolean } = {}): number {
  return getActiveDynastyIds(year, opts).length;
}

/** Years where the set of active realms changes, ascending. Useful for snapping and the timeline. */
export function changePoints(): number[] {
  const pts = new Set<number>();
  for (const r of realms) { pts.add(r.start); pts.add(r.end + 1); }
  return [...pts].sort((a, b) => a - b);
}

export interface Reach {
  dynastyId: string;
  regions: { regionId: string; relation: Relation; confidence: Confidence; core: boolean }[];
  coreRegionCount: number;
  /** Who else held land in the regions this dynasty touched, at the same year. */
  concurrentDynastyIds: string[];
}

/** What a dynasty actually held at `year`, and who ruled alongside it ("reach lens"). */
export function getReach(dynastyId: string, year: number): Reach {
  const active = getRealmsAt(year);
  const own = active.filter(r => r.dynastyId === dynastyId);
  const regionIds = new Set(own.map(r => r.regionId));
  const regions = own
    .map(r => ({ regionId: r.regionId, relation: r.relation, confidence: r.confidence, core: r.core }))
    .sort((a, b) => a.regionId.localeCompare(b.regionId));
  const others = new Set(active.filter(r => r.dynastyId !== dynastyId && regionIds.has(r.regionId)).map(r => r.dynastyId));
  return {
    dynastyId,
    regions,
    coreRegionCount: new Set(own.filter(r => r.core).map(r => r.regionId)).size,
    concurrentDynastyIds: [...others].sort(),
  };
}

// ── Ranking & per-region views (used by the map) ─────────────────────────────

/** Higher = stronger hold on a region. Used to pick the dynasty that colours it. */
export const RELATION_RANK: Record<Relation, number> = {
  direct: 7, branch: 6, governor: 5, suzerain: 4, vassal: 3, occupation: 2, influence: 1,
};

/** 0–1 "how firmly held", drives fill opacity (mirrors the legend: direct → influence). */
export const RELATION_EXTENT: Record<Relation, number> = {
  direct: 0.9, branch: 0.8, governor: 0.7, suzerain: 0.55, vassal: 0.55, occupation: 0.3, influence: 0.25,
};

const CONF_RANK: Record<Confidence, number> = { low: 0, medium: 1, high: 2 };

/** Strongest first; ties broken by confidence, then dynasty id (deterministic). */
export function rankRealms(list: Realm[]): Realm[] {
  return [...list].sort((a, b) =>
    RELATION_RANK[b.relation] - RELATION_RANK[a.relation] ||
    CONF_RANK[b.confidence] - CONF_RANK[a.confidence] ||
    a.dynastyId.localeCompare(b.dynastyId)
  );
}

let cachedYear: number | null = null;
let cachedByRegion: Map<string, Realm[]> = new Map();

/** regionId → realms in force at `year`, strongest first, one entry per dynasty. Cached for the last year asked. */
export function getRealmsByRegion(year: number): Map<string, Realm[]> {
  if (cachedYear === year) return cachedByRegion;
  const grouped = new Map<string, Realm[]>();
  for (const r of getRealmsAt(year)) {
    if (!grouped.has(r.regionId)) grouped.set(r.regionId, []);
    grouped.get(r.regionId)!.push(r);
  }
  const out = new Map<string, Realm[]>();
  for (const [regionId, list] of grouped) {
    const seen = new Set<string>();
    out.set(regionId, rankRealms(list).filter(r => (seen.has(r.dynastyId) ? false : (seen.add(r.dynastyId), true))));
  }
  cachedYear = year;
  cachedByRegion = out;
  return out;
}
